 "content": "def transform(grid):
    """Slide the lone colored object against the straight 2-wall; mark its original centerline in 8."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find a full divider line of 2s.
    wall = None
    for r, row in enumerate(grid):
        if all(v == 2 for v in row):
            wall = ('h', r)
            break
    if wall is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                wall = ('v', c)
                break
    if wall is None:
        return [row[:] for row in grid]
    obj_color = next(v for v in Counter(v for row in grid for v in row).most_common() if v[0] not in (bg, 2))[0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj_color]
    if not pts:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    if wall[0] == 'h':
        wr = wall[1]
        center = int(sum(r for r, c in pts) / len(pts) + 0.5)
        if max(r for r, c in pts) < wr:
            dr = wr - 1 - max(r for r, c in pts)
        else:
            dr = wr + 1 - min(r for r, c in pts)
        out = [[8 if r == center and grid[r][c] != 2 else grid[r][c] for c in range(w)] for r in range(h)]
        for r, c in pts:
            out[r + dr][c] = obj_color
    else:
        wc = wall[1]
        center = int(sum(c for r, c in pts) / len(pts) + 0.5)
        if max(c for r, c in pts) < wc:
            dc = wc - 1 - max(c for r, c in pts)
        else:
            dc = wc + 1 - min(c for r, c in pts)
        out = [[8 if c == center and grid[r][c] != 2 else grid[r][c] for c in range(w)] for r in range(h)]
        for r, c in pts:
            out[r][c + dc] = obj_color
    return out
